alter table public.guftin_site_settings
  add column if not exists intro_title text not null default 'Conversations in one place.',
  add column if not exists intro_paragraph_one text not null default 'Guftin is a communication app designed around direct conversations and shared moments. Its current Android source includes email-based accounts, username profiles, direct and group chats, media sharing, status updates and settings for everyday use.',
  add column if not exists intro_paragraph_two text not null default 'Voice and video calling are part of the app implementation and depend on the required calling service configuration. Feature availability can vary while services are being configured and tested.',
  add column if not exists feature_1_title text not null default 'Direct messaging',
  add column if not exists feature_1_description text not null default 'Find people by Guftin username and keep one-to-one conversations together.',
  add column if not exists feature_2_title text not null default 'Group conversations',
  add column if not exists feature_2_description text not null default 'Create group spaces and share messages with other members.',
  add column if not exists feature_3_title text not null default 'Media and documents',
  add column if not exists feature_3_description text not null default 'Choose photos, videos, voice messages and supported documents to share.',
  add column if not exists feature_4_title text not null default 'Status updates',
  add column if not exists feature_4_description text not null default 'Post updates with views and reactions. Status posts are designed to leave normal viewing after 24 hours.',
  add column if not exists feature_5_title text not null default 'Voice and video calls',
  add column if not exists feature_5_description text not null default 'Calling features are included in the Android app code and require the configured LiveKit service.',
  add column if not exists feature_6_title text not null default 'Personal controls',
  add column if not exists feature_6_description text not null default 'Manage online visibility, read receipts, push notifications, media auto-save and sync preferences.',
  add column if not exists experience_title text not null default 'Less clutter. More connection.',
  add column if not exists experience_description text not null default 'Move between chats, groups, updates and profile controls in one app.',
  add column if not exists footer_tagline text not null default 'One space for everyday connection.';
